mapper.select:
SELECT proc.product_code , proc.name AS product_name , wrhs.warehouse_code , wrhs.name AS warehouse_name , ires.result_qty , ires.result_date FROM inbound_results AS ires JOIN inbound_schedules AS isch ON ires.company_id = isch.company_id AND ires.inbound_schedule_id = isch.inbound_schedule_id JOIN products AS proc ON isch.company_id = proc.company_id AND isch.product_id = proc.product_id JOIN warehouses AS wrhs ON isch.company_id = wrhs.company_id AND isch.warehouse_id = wrhs.warehouse_id WHERE ires.company_id = #{companyId}
AND proc.product_code LIKE CONCAT('%', #{productCode}, '%')
AND proc.name LIKE CONCAT('%', #{productName}, '%')
AND wrhs.warehouse_code LIKE CONCAT('%', #{warehouseCode}, '%')
AND wrhs.name LIKE CONCAT('%', #{warehouseName}, '%')
AND ires.result_date >= #{resultDateFrom}
AND ires.result_date <= #{resultDateTo}
ORDER BY ires.inbound_result_id;
